            const sent = cap(order.map(i => s[i]).join(' ')) + '.';
            return { type: 'one', q: `«${sent}» ${qi === 1 ? 'Какие слова называют действие — что делали?' : `Какие слова отвечают на вопрос «${QW[qi]}?»`}`, a: s.slice(), c: qi, why: `Кто? — ${s[0]}. Действие — ${s[1]}. Где? — ${s[2]}. Когда? — ${s[3]}. Слова-улики помогают быстро понять предложение.` };
