        const norm = { 3: 15, 4: 30, 5: 45 }[n], v = Math.min(1, norm / sec) * (errs > 2 ? 0.7 : 1); tr(v); award(sec <= norm ? 3 : 1, 5); if (n === 5 && sec <= 40 && !errs) awardGems(1, 'за молниеносную таблицу 5×5');
        $('#sres').innerHTML = `<div class="center g-result"><h2>${sec} с ${rec ? '🏆 Рекорд!' : ''}</h2><p>${sec <= norm ? 'Отличное поле зрения!' : 'Хорошо! Тренируйся каждый день — время будет падать.'}${errs ? ` Ошибок: ${errs}.` : ''}</p><div class="row-btns"><button class="btn pink" id="sag">Ещё раз</button>${n < 5 ? `<button class="btn" id="sup">${n + 1}×${n + 1} →</button>` : ''}</div></div>`;
        $('#sag').addEventListener('click', () => go('schulte', n)); $('#sup')?.addEventListener('click', () => go('schulte', n + 1));
